import React, { useState, useEffect } from 'react';
import Chart from './components/Chart';
import Dropdowns from './components/Dropdowns';
import TradeInfo from './components/TradeInfo';
import { fetchMarketData } from '../services/marketData';
import { TradeSignal } from '../types';

const App: React.FC = () => {
    const [marketData, setMarketData] = useState<any>(null);
    const [tradeSignal, setTradeSignal] = useState<TradeSignal | null>(null);

    useEffect(() => {
        const getMarketData = async () => {
            const data = await fetchMarketData();
            setMarketData(data);
        };

        getMarketData();
        const interval = setInterval(getMarketData, 5000); // Fetch market data every 5 seconds

        return () => clearInterval(interval);
    }, []);

    return (
        <div>
            <h1>Forex Trade Helper Bot</h1>
            <Dropdowns setTradeSignal={setTradeSignal} />
            <Chart marketData={marketData} />
            {tradeSignal && <TradeInfo tradeSignal={tradeSignal} />}
        </div>
    );
};

export default App;
